content:
{
    "criteria": [
        {
            "id": "C1",
            "section": "合同主体审查",
            "criterion": "核实签约主体合法性与信息一致性",
            "check_points": [
                "通过国家企业信用信息公示系统或司法大数据平台核查该主体是否存在未结重大涉诉、被执行、失信、严重违法等风险信息",
                "核对营业执照登记的经营范围，确认合同标的（如软件采购）属于其核准经营范围内",
                "逐项比对合同首部列明的主体信息（名称、统一社会信用代码、注册地址、联系电话、传真、法定代表人/负责人姓名及职务、指定联系人及联系方式）与最新工商登记信息是否完全一致",
                "如涉及软件等技术产品采购，核查卖方是否拥有该产品核心知识产权（如著作权登记证书、专利证书或授权链条文件），并明确约定权属归属及许可范围"
            ]
        },
        {
            "id": "C2",
            "section": "合同框架完整性审查",
            "criterion": "确保合同核心条款全面覆盖关键履约要素",
            "check_points": [
                "检查合同是否完整包含以下必备条款：采购内容、合同金额、付款计划、合同期限、生效条件、知识产权归属与使用限制、产品质量/服务标准及保证、交付方式与地点、验收标准与程序、完成时限（含里程碑节点）、违约责任（含违约金计算方式与上限）、争议解决方式（管辖法院或仲裁机构）、不可抗力定义与处理机制、廉洁承诺条款、合同变更程序、合同份数及效力说明、电子送达有效性约定",
                "确认合同中已明确指定主要项目负责人，并完整载明其姓名、身份证号码及联系电话",
                "核查采购内容是否具体列明品种、规格、型号、等级、花色等技术参数；若内容复杂，是否通过附件形式固化并注明‘附件为本合同不可分割组成部分’",
                "核验合同金额是否同时载明大小写、币种、计量单位；单价、数量、总价是否逻辑对应；是否存在漏计税费、运费、安装调试费等隐含成本",
                "审查付款计划是否设置清晰节点（如预付款、到货款、验收款、质保金），质保金比例是否合理（建议不低于5%），是否明确约定‘质保金于免费维保期届满且无质量异议后X个工作日内无息支付’，并注明发票类型（如增值税专用发票）及开票时限"
            ]
        },
        {
            "id": "C3",
            "section": "合同期限与时间表述审查",
            "criterion": "确保期限约定明确、无歧义，符合实务操作要求",
            "check_points": [
                "合同期限是否以起止日期（年月日）或明确周期（如‘自2025年1月1日起至2026年12月31日止’）方式载明，避免使用‘长期’‘永久’等模糊表述",
                "是否明确定义时间计算基准（如‘自然日’或‘工作日’），对‘季度’‘年度’等周期是否作出解释（例如‘自然季度’或‘自起始日起每满三个月为一个履约季度’）",
                "关键时间节点（如交付日、验收启动日、付款触发日）是否与合同期限逻辑自洽，是否存在倒挂或冲突"
            ]
        },
        {
            "id": "C4",
            "section": "文本规范性与一致性审查",
            "criterion": "保障合同语言严谨、格式统一、内容无矛盾",
            "check_points": [
                "全文通读排查错别字、标点误用、语法错误、语义重复或逻辑断裂等文字瑕疵",
                "核对合同正文与所有附件（如技术规格书、服务清单、报价明细）中关于同一事项（如付款条件、验收标准、知识产权归属）的约定是否完全一致，存在差异时须以合同正文为准并作特别说明",
                "清除招标文件、谈判纪要、询价函等前期流程性文件中残留的非合同用语（如‘投标单位’‘响应人’‘谈判小组’等），统一使用‘甲方’‘乙方’‘双方’等合同主体称谓",
                "确认合同首部‘甲方/乙方’全称与签署页‘签订主体名称’完全一致（包括括号、空格、简称与全称对应关系），杜绝首部为‘XX有限公司’而签章处为‘XX集团有限公司’等不一致情形",
                "核查所援引法律、法规、规章或标准文件（如《民法典》第XXX条、GB/T XXXX-XXXX）是否现行有效，名称与文号是否准确无误",
                "确认合同正文末尾是否规范标注‘以下为合同签署栏’或‘以下无正文’字样，防止签署页被篡改或增补"
            ]
        }
    ]
}
